import{_ as a,o as r,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Professions in Syrolands","description":"","frontmatter":{},"headers":[],"relativePath":"guide/professions/overview.md","filePath":"guide/professions/overview.md"}'),o={name:"guide/professions/overview.md"};function i(s,e,l,d,c,h){return r(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="professions-in-syrolands" tabindex="-1">Professions in Syrolands <a class="header-anchor" href="#professions-in-syrolands" aria-label="Permalink to &quot;Professions in Syrolands&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> This page describes the intended redesign, not confirmed live mechanics. <strong>Implementation/availability:</strong> not established for this redesign. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-08 against the <a href="/Syrolands-Public/game-design/professions/profession-system.html">full design specification</a>.</p><h2 id="crafts-belong-to-adventurers" tabindex="-1">Crafts belong to adventurers <a class="header-anchor" href="#crafts-belong-to-adventurers" aria-label="Permalink to &quot;Crafts belong to adventurers&quot;">​</a></h2><p>“There are no crafter characters; there are characters who know crafts.” Professions should matter while exploring, surviving, maintaining equipment, fighting where appropriate and participating in the economy—not only while standing in a workshop.</p><p>They share the character&#39;s overall skill budget. Knowing a craft should create useful choices rather than supply a generic combat buff.</p><h2 id="learning-and-becoming-known" tabindex="-1">Learning and becoming known <a class="header-anchor" href="#learning-and-becoming-known" aria-label="Permalink to &quot;Learning and becoming known&quot;">​</a></h2><p>The proposed path begins with a starting competency or basic instruction, followed by practice and discovery. Low skill should already be useful. The direction is roughly a 700-point total cap and 100 normal maximum, with increasingly slow gains near mastery; these are not finalized settings. Endgame beyond 100 comes from knowledge, techniques, reputation and player understanding.</p><p>A <strong>skill</strong> is broad capability. A <strong>technique</strong> is learned knowledge, such as Bowmaking or Distillation. A <strong>profession path</strong> combines skill, techniques and practice. Your <strong>identity</strong> is what others know you for: perhaps especially durable war bows or beautiful garments.</p><p>You do not need seven skills at 100 to be viable. Supporting skills and practical knowledge should make hybrid characters worthwhile.</p><h2 id="knowledge-and-production" tabindex="-1">Knowledge and production <a class="header-anchor" href="#knowledge-and-production" aria-label="Permalink to &quot;Knowledge and production&quot;">​</a></h2><p>Each character should build a profession journal through observation, teachers, books, exploration and experiments. Reaching 100 would not reveal everything. Shared advice helps, but materials and execution still matter: knowledge can be shared; mastery cannot be copied.</p><p>Manual work establishes understanding. Known procedures may then support time-consuming production batches at a station, with real materials and interruptions. Commissions should ask for useful results, and reputation should reflect what you make well rather than a single rating.</p><h2 id="explore-the-professions" tabindex="-1">Explore the professions <a class="header-anchor" href="#explore-the-professions" aria-label="Permalink to &quot;Explore the professions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Profession</th><th>Proposed role</th></tr></thead><tbody><tr><td><a href="/Syrolands-Public/guide/professions/cooking.html">Cooking</a></td><td>Food, preparation, discovery and survival</td></tr><tr><td><a href="/Syrolands-Public/guide/professions/alchemy.html">Alchemy</a></td><td>Reactions, preparations and field support</td></tr><tr><td><a href="/Syrolands-Public/guide/professions/mining.html">Mining</a></td><td>Geology, extraction and authored excavation</td></tr><tr><td><a href="/Syrolands-Public/guide/professions/blacksmithing.html">Blacksmithing</a></td><td>Metallurgy, equipment and maintenance</td></tr><tr><td><a href="/Syrolands-Public/guide/professions/tailoring.html">Tailoring</a></td><td>Flexible materials, fit, protection and fashion</td></tr><tr><td><a href="/Syrolands-Public/guide/professions/lumberjacking.html">Lumberjacking</a></td><td>Forestry, timber selection and felling</td></tr><tr><td><a href="/Syrolands-Public/guide/professions/carpentry.html">Carpentry</a></td><td>Woodwork, construction and learned Bowmaking</td></tr><tr><td><a href="/Syrolands-Public/guide/professions/tinkering.html">Tinkering</a></td><td>Precision mechanisms, security and devices</td></tr></tbody></table><p><a href="/Syrolands-Public/guide/items/item-quality.html">Item Quality / Masterworks</a> explains why good materials, technique and execution should matter more than a lucky roll. Skills, world protections, exact learning rules and economic balance still need reconciliation before implementation.</p><h2 id="shared-character-rules" tabindex="-1">Shared character rules <a class="header-anchor" href="#shared-character-rules" aria-label="Permalink to &quot;Shared character rules&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/characters/progression.html">Character progression</a>, <a href="/Syrolands-Public/guide/characters/skills.html">skills and teachers</a>, <a href="/Syrolands-Public/guide/characters/techniques.html">techniques</a> and <a href="/Syrolands-Public/guide/characters/character-creation.html">backgrounds</a> explain the shared framework. Profession-specific discovery, production and reputation build on it.</p><h2 id="inscription-and-magical-knowledge" tabindex="-1">Inscription and magical knowledge <a class="header-anchor" href="#inscription-and-magical-knowledge" aria-label="Permalink to &quot;Inscription and magical knowledge&quot;">​</a></h2><p><a href="/Syrolands-Public/guide/professions/inscription.html">Inscription</a> extends the Proposed shared framework to scrolls, variants, grimoires and notation. Learning/copying permissions remain distinct from crafting capability; physical materials and valuable books retain loot risk.</p>',19)])])}const g=a(o,[["render",i]]);export{p as __pageData,g as default};
